    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 70-year-old man presents with a rapidly growing, painless, firm, red-violet nodule on his sun-exposed cheek. Biopsy reveals a neuroendocrine tumor of the skin that stains positively for Cytokeratin 20 (CK20) in a classic "perinuclear dot" pattern. What is the diagnosis?', '["Basal cell carcinoma", "Merkel cell carcinoma", "Squamous cell carcinoma", "Melanoma", "Cutaneous lymphoma"]'::jsonb, 1, 'Merkel cell carcinoma is a rare, highly aggressive neuroendocrine carcinoma of the skin. It frequently presents as a rapidly expanding red/purple nodule. CK20 positivity (perinuclear dot pattern) is the classic immunohistochemical hallmark.'),
    (v_topic_id, 'Which virus is strongly implicated in the pathogenesis of the majority of Merkel cell carcinomas?', '["Human papillomavirus (HPV)", "Epstein-Barr virus (EBV)", "Merkel cell polyomavirus (MCPyV)", "Human herpesvirus 8 (HHV-8)", "Hepatitis C virus (HCV)"]'::jsonb, 2, 'The Merkel cell polyomavirus (MCPyV) is found clonally integrated into the genome of approximately 80% of Merkel cell carcinomas, playing a direct oncogenic role.'),
    (v_topic_id, 'What is the appropriate management for the clinically negative neck (N0) in a patient diagnosed with Merkel cell carcinoma of the face?', '["Observation only", "Empiric systemic chemotherapy", "Sentinel lymph node biopsy (SLNB) or elective neck dissection", "Wait for palpable nodes to develop", "Topical imiquimod"]'::jsonb, 2, 'Merkel cell carcinoma has a very high rate of early regional lymphatic spread (up to 30% even when clinically N0). Staging the regional lymph nodes with SLNB or elective neck dissection/radiation is mandatory.'),
    (v_topic_id, 'An 80-year-old man presents with a non-healing, yellowish, crusting nodule on his upper eyelid. He has a history of chronic blepharoconjunctivitis that has not responded to topical antibiotics. Biopsy reveals a malignancy arising from the meibomian glands. What is the diagnosis?', '["Basal cell carcinoma", "Sebaceous carcinoma", "Melanoma", "Squamous cell carcinoma", "Merkel cell carcinoma"]'::jsonb, 1, 'Sebaceous carcinoma is a rare, aggressive malignancy that classically arises from the meibomian glands of the eyelid (more commonly the upper lid). It frequently masquerades clinically as a benign chalazion or chronic blepharitis.'),
    (v_topic_id, 'Sebaceous carcinoma, along with multiple keratoacanthomas and visceral malignancies (particularly colon cancer), is the hallmark of which genetic syndrome?', '["Muir-Torre syndrome", "Gorlin syndrome", "Cowden syndrome", "Peutz-Jeghers syndrome", "Gardner syndrome"]'::jsonb, 0, 'Muir-Torre syndrome is an autosomal dominant condition (a variant of Lynch syndrome) characterized by skin tumors (sebaceous neoplasms, keratoacanthomas) and internal malignancies, most commonly colorectal cancer.'),
    (v_topic_id, 'A 45-year-old woman presents with a slow-growing, indurated, plaque-like lesion on her scalp that resembles a scar. Biopsy shows spindle cells in a classic "cartwheel" or "storiform" pattern infiltrating the subcutaneous fat. What is the diagnosis?', '["Squamous cell carcinoma", "Basal cell carcinoma", "Dermatofibrosarcoma protuberans (DFSP)", "Angiosarcoma", "Melanoma"]'::jsonb, 2, 'DFSP is a locally aggressive, rare cutaneous soft tissue sarcoma. It classically presents as a firm, indurated plaque that looks like a keloid scar and histologically features spindle cells in a storiform pattern. It rarely metastasizes but has a high local recurrence rate.'),
    (v_topic_id, 'An elderly patient presents with a rapidly spreading, poorly defined, bruise-like (ecchymotic) patch on the scalp that has progressed to raised, bleeding nodules. Biopsy confirms a highly aggressive vascular malignancy. What is the diagnosis?', '["Kaposi sarcoma", "Hemangioma", "Cutaneous angiosarcoma", "Pyogenic granuloma", "Melanoma"]'::jsonb, 2, 'Cutaneous angiosarcoma is an exceptionally aggressive malignancy of endothelial cells. It classically presents on the scalp and face of elderly patients as a spreading, bruise-like lesion. The prognosis is exceedingly poor.'),
    (v_topic_id, 'Which of the following is a classic risk factor for the development of angiosarcoma?', '["Tobacco use", "Chronic sun exposure alone", "Prior radiation therapy or chronic lymphedema (Stewart-Treves syndrome)", "HPV infection", "EBV infection"]'::jsonb, 2, 'While idiopathic cases occur, prior radiation therapy to the area (e.g., post-mastectomy radiation) or chronic lymphedema are very strong risk factors for the development of angiosarcoma years later.'),
    (v_topic_id, 'A 3-week-old infant is brought in for a unilateral, firm, non-tender mass in the sternocleidomastoid muscle. The infant keeps her head tilted toward the side of the mass and rotated to the opposite side (torticollis). What is the most likely diagnosis?', '["Branchial cleft cyst", "Cystic hygroma", "Fibromatosis colli (pseudotumor of infancy)", "Rhabdomyosarcoma", "Thyroglossal duct cyst"]'::jsonb, 2, 'Fibromatosis colli is a benign fibroblastic proliferation within the sternocleidomastoid muscle, usually presenting 2-4 weeks after birth (often following a difficult delivery). It presents as a firm mass causing congenital muscular torticollis.'),
    (v_topic_id, 'What is the standard, primary treatment for Fibromatosis colli?', '["Surgical excision of the mass", "Radiation therapy", "Chemotherapy", "Physical therapy and stretching exercises", "Intralesional steroid injection"]'::jsonb, 3, 'Fibromatosis colli is a benign, self-limiting condition that spontaneously resolves over several months in over 90% of cases. The treatment is conservative physical therapy (stretching the SCM muscle) to prevent permanent torticollis.'),
    (v_topic_id, 'A 2-month-old infant presents with a rapidly growing, bright red, raised, "strawberry-like" nodule on the cheek. It was not present at birth but appeared at 2 weeks of age. What is the characteristic natural history of this lesion?', '["It will rapidly metastasize", "It will continue to grow throughout adulthood", "It will undergo rapid proliferation for 6-12 months, followed by slow, spontaneous involution (shrinking) over several years", "It will require immediate, radical surgical excision", "It will transform into an angiosarcoma"]'::jsonb, 2, 'Infantile hemangiomas are the most common benign tumors of infancy. Their defining feature is their clinical course: absence at birth, rapid proliferation during the first year, and spontaneous involution by age 5-10.'),
    (v_topic_id, 'An infant has a massive infantile hemangioma in the "beard distribution" (lower face, chin, anterior neck). What hidden, potentially life-threatening complication must be immediately ruled out with airway endoscopy?', '["Brain metastasis", "Subglottic hemangioma causing airway obstruction", "Esophageal stricture", "Vocal cord paralysis", "Tracheoesophageal fistula"]'::jsonb, 1, 'Infants with large or multiple hemangiomas in the "beard" distribution have a high risk (up to 60%) of having a concurrent airway (subglottic) hemangioma, which can rapidly grow and cause fatal airway obstruction.'),
    (v_topic_id, 'If an infantile hemangioma requires medical treatment (e.g., because it is obstructing vision, encroaching on the airway, or causing severe ulceration), what is the first-line systemic medication of choice?', '["Systemic corticosteroids", "Vincristine", "Propranolol (a non-selective beta-blocker)", "Interferon-alpha", "Bleomycin"]'::jsonb, 2, 'Oral propranolol has revolutionized the treatment of problematic infantile hemangiomas, rapidly inducing cessation of growth and accelerating involution. It has largely replaced systemic steroids as the first-line therapy.'),
    (v_topic_id, 'A 15-year-old girl presents with a painless, midline neck mass located just above the sternal notch. It moves with swallowing but does NOT move with tongue protrusion. What is the most likely diagnosis?', '["Thyroglossal duct cyst", "Dermoid cyst", "Branchial cleft cyst", "Thyroid nodule", "Delphian node"]'::jsonb, 1, 'Dermoid cysts are developmental cysts that often present in the midline neck. Unlike thyroglossal duct cysts (which move upward with tongue protrusion due to their attachment to the foramen cecum at the base of the tongue), dermoid cysts generally do not move with tongue protrusion.'),
    (v_topic_id, 'During the evaluation of a patient with suspected Hodgkin lymphoma presenting with a rubbery, painless cervical lymph node, an excisional biopsy is performed. What is the pathognomonic cellular finding required for the diagnosis?', '["Homer-Wright rosettes", "Reed-Sternberg cells (large, binucleated cells with prominent nucleoli resembling \"owl eyes\")", "Small round blue cells", "Psammoma bodies", "Orphan Annie eye nuclei"]'::jsonb, 1, 'The diagnosis of Hodgkin lymphoma absolutely requires the identification of Reed-Sternberg cells (or their variants) within a supportive inflammatory background.'),
    (v_topic_id, 'A 25-year-old male presents with rubbery, non-tender cervical lymphadenopathy. He reports that the lymph nodes become acutely painful shortly after he drinks alcohol. He also reports severe night sweats and generalized pruritus. What is the most likely diagnosis?', '["Non-Hodgkin lymphoma", "Hodgkin lymphoma", "Metastatic squamous cell carcinoma", "Tuberculosis (scrofula)", "Infectious mononucleosis"]'::jsonb, 1, 'While rare, alcohol-induced lymph node pain is a highly specific symptom of Hodgkin lymphoma. Night sweats, fever, and weight loss are classic "B symptoms," which carry prognostic significance.'),
    (v_topic_id, 'A 50-year-old woman presents with severe, chronic ear pain (otalgia) on the right side and purulent otorrhea (ear drainage) for 3 months. She has been treated with multiple courses of topical drops without improvement. Examination shows granulation tissue in the floor of the external auditory canal at the bony-cartilaginous junction. She is a poorly controlled diabetic. What is the most likely diagnosis?', '["Malignant otitis externa (necrotizing otitis externa)", "Acute otitis media", "Squamous cell carcinoma of the ear canal", "Cholesteatoma", "Furunculosis"]'::jsonb, 0, 'Malignant otitis externa is an aggressive, life-threatening osteomyelitis of the temporal bone, almost exclusively occurring in elderly diabetics or immunocompromised patients. It typically starts in the external auditory canal.'),
    (v_topic_id, 'What is the classic causative pathogen responsible for Malignant (Necrotizing) Otitis Externa?', '["Staphylococcus aureus", "Streptococcus pneumoniae", "Pseudomonas aeruginosa", "Candida albicans", "Haemophilus influenzae"]'::jsonb, 2, 'Pseudomonas aeruginosa is the culprit pathogen in >95% of cases of malignant otitis externa. Treatment requires prolonged (weeks to months) systemic antipseudomonal antibiotics (e.g., IV ciprofloxacin or ceftazidime).'),
    (v_topic_id, 'In a patient being treated for Malignant Otitis Externa, what complication indicates advanced disease and a significantly worse prognosis?', '["Development of a tympanic membrane perforation", "Involvement of the cranial nerves (most commonly the Facial nerve, CN VII), indicating extensive osteomyelitis of the skull base", "Development of tinnitus", "Mild conductive hearing loss", "A positive culture for Pseudomonas"]'::jsonb, 1, 'Cranial nerve palsies (CN VII, IX, X, XI, XII) indicate that the infection has spread deeply into the temporal bone and skull base foramina. This is a sign of advanced, life-threatening disease.'),
    (v_topic_id, 'A 60-year-old man, with no history of diabetes, presents with chronic bloody ear drainage, severe pain, and a fleshy mass completely occluding the external auditory canal. Biopsy confirms Squamous Cell Carcinoma of the external auditory canal. What is the most common predisposing risk factor for this rare malignancy?', '["Chronic sun exposure", "Chronic otitis media or chronic otitis externa (long-standing inflammation)", "Smoking", "HPV infection", "Loud noise exposure"]'::jsonb, 1, 'Unlike cutaneous SCC of the pinna (which is caused by sun exposure), SCC of the external auditory canal is strongly associated with a long history of chronic inflammation and infection (chronic otitis media/externa).'),
    (v_topic_id, 'For an early-stage (T1 or T2) squamous cell carcinoma confined to the external auditory canal without erosion into the middle ear, what is the standard surgical procedure?', '["Simple excision with a scalpel", "Lateral temporal bone resection (removal of the entire bony external auditory canal, tympanic membrane, and malleus/incus en bloc)", "Subtotal temporal bone resection", "Total temporal bone resection", "Mastoidectomy alone"]'::jsonb, 1, 'Lateral temporal bone resection provides an en bloc, margin-negative resection of the external auditory canal while preserving the facial nerve and the inner ear (cochlea/vestibule).'),
    (v_topic_id, 'A patient is diagnosed with a vestibular schwannoma (acoustic neuroma). From which specific nerve does this tumor almost universally originate?', '["The facial nerve (CN VII)", "The cochlear nerve", "The superior or inferior vestibular nerve (branches of CN VIII)", "The glossopharyngeal nerve (CN IX)", "The vagus nerve (CN X)"]'::jsonb, 2, 'Despite the name "acoustic neuroma," these tumors are schwannomas that arise from the myelin-forming Schwann cells of the vestibular divisions of the eighth cranial nerve, most commonly within the internal auditory canal.'),
    (v_topic_id, 'What is the classic, most common presenting audiologic symptom of a vestibular schwannoma?', '["Sudden, bilateral conductive hearing loss", "Unilateral, progressive sensorineural hearing loss (especially in the high frequencies) and poor speech discrimination", "Fluctuating hearing loss with episodic vertigo", "Bilateral symmetrical hearing loss in an elderly patient", "Hyperacusis"]'::jsonb, 1, 'As the tumor grows, it compresses the adjacent cochlear nerve. Patients typically present with asymmetric or unilateral sensorineural hearing loss, often accompanied by unilateral tinnitus.'),
    (v_topic_id, 'Which radiologic study is the gold standard for diagnosing and evaluating a suspected vestibular schwannoma?', '["CT scan of the temporal bone without contrast", "Gadolinium-enhanced MRI of the brain and internal auditory canals", "PET scan", "Ultrasound of the neck", "Plain X-ray of the skull"]'::jsonb, 1, 'An MRI with gadolinium contrast is exquisitely sensitive for detecting vestibular schwannomas, even those as small as 1-2 mm confined entirely within the internal auditory canal.'),
    (v_topic_id, 'When surgically resecting a large vestibular schwannoma using a translabyrinthine approach, what permanent deficit is an absolute, inevitable consequence of the surgical approach itself?', '["Complete facial nerve paralysis", "Total, irreversible sensorineural hearing loss (anacusis) in the operated ear", "Loss of taste", "Difficulty swallowing", "Blindness"]'::jsonb, 1, 'The translabyrinthine approach drills directly through the semicircular canals and the cochlea to access the internal auditory canal and cerebellopontine angle, resulting in guaranteed, complete loss of hearing and vestibular function on that side. It is chosen for large tumors or when hearing is already non-salvageable, as it provides excellent visualization of the facial nerve.'),
    (v_topic_id, 'A patient develops a cerebrospinal fluid (CSF) leak (rhinorrhea) following surgery for a sinonasal tumor at the skull base. A fluid sample is sent to the lab. Which specific protein assay is the most highly sensitive and specific for confirming that the fluid is CSF?', '["Glucose", "Total protein", "Beta-2 transferrin", "Amylase", "Alkaline phosphatase"]'::jsonb, 2, 'Beta-2 transferrin is an isoform of transferrin that is found almost exclusively in CSF, perilymph, and aqueous humor. Its presence in nasal drainage is the gold standard diagnostic test for a CSF leak.'),
    (v_topic_id, 'If a patient presents with clear rhinorrhea after head trauma, which bedside clinical sign (though not highly specific) suggests the fluid might be a mixture of blood and CSF?', '["Battle''s sign", "The \"Halo\" or \"Target\" sign on filter paper (a central red spot of blood surrounded by a clear ring of faster-diffusing CSF)", "Trousseau''s sign", "Kernig''s sign", "Brudzinski''s sign"]'::jsonb, 1, 'The halo sign occurs because CSF is less viscous and diffuses faster outward on filter paper or bed linens than the cellular components of blood. While classic, it is not perfectly specific and should be confirmed with a Beta-2 transferrin test.'),
    (v_topic_id, 'What is the most serious and potentially fatal complication of an untreated cerebrospinal fluid (CSF) leak at the anterior skull base?', '["Deafness", "Blindness", "Ascending bacterial meningitis", "Encephalocele formation", "Anosmia"]'::jsonb, 2, 'A persistent bony and dural defect creates a direct pathway for bacteria from the non-sterile nasal cavity to enter the sterile subarachnoid space, carrying a high risk of fatal meningitis.'),
    (v_topic_id, 'A 45-year-old patient requires reconstruction of a large, complex defect of the midface following a total maxillectomy. The surgeon decides to use an anterolateral thigh (ALT) free flap. The ALT flap receives its blood supply from the descending branch of which major artery?', '["Femoral artery", "Profunda femoris (deep femoral) artery via the lateral circumflex femoral artery", "Popliteal artery", "Internal iliac artery", "Obturator artery"]'::jsonb, 1, 'The ALT flap is a versatile workhorse flap based on perforators from the descending branch of the lateral circumflex femoral artery, which is a branch of the profunda femoris.'),
    (v_topic_id, 'When harvesting a radial forearm free flap, it is critical to ensure that the hand will continue to receive adequate blood flow after the radial artery is sacrificed. What preoperative clinical test is absolutely mandatory to confirm collateral circulation to the hand?', '["The Allen test", "Phalen''s test", "Tinel''s test", "Finkelstein''s test", "Adson''s test"]'::jsonb, 0, 'The Allen test evaluates the patency of the palmar arch and the collateral blood flow from the ulnar artery. If the ulnar artery cannot adequately supply the hand when the radial artery is occluded, harvesting a radial forearm flap is contraindicated to avoid ischemic necrosis of the hand.'),
    (v_topic_id, 'A patient undergoes a free tissue transfer (free flap) reconstruction. On postoperative day 2, the nursing staff notes that the skin paddle of the flap has become suddenly pale, cold, and capillary refill is completely absent. The handheld Doppler detects no pulse. What does this clinical picture indicate?', '["Normal postoperative swelling", "Venous congestion (thrombosis of the venous anastomosis)", "Arterial occlusion (thrombosis of the arterial anastomosis)", "Infection of the flap", "Hematoma under the flap"]'::jsonb, 2, 'A pale, cold, pulseless flap with no capillary refill indicates a complete failure of arterial inflow. This is an absolute surgical emergency requiring immediate return to the operating room for anastomotic revision. In contrast, venous congestion presents with a dark blue/purple, warm, swollen flap with very brisk capillary refill.'),
    (v_topic_id, 'If a free flap exhibits signs of severe venous congestion (dark purple color, swollen, brisk capillary refill) that cannot be immediately salvaged with surgical revision, what adjunctive biological therapy is commonly applied to the flap surface to relieve the venous engorgement and improve survival?', '["Topical antibiotics", "Warm compresses", "Medicinal leeches (Hirudo medicinalis)", "Steroid cream", "Silver sulfadiazine"]'::jsonb, 2, 'Leeches are used for venous salvage. They actively remove congested blood, and their saliva contains hirudin (a potent anticoagulant) which allows the bite wound to continue bleeding and decompressing the flap for hours after the leech falls off. This buys time for new venous outflow (neovascularization) to develop.'),
    (v_topic_id, 'When utilizing medicinal leeches for flap salvage, patients must be placed on prophylactic antibiotics to cover which specific bacterium that naturally colonizes the leech gut and can cause aggressive flap infections?', '["Staphylococcus aureus", "Pseudomonas aeruginosa", "Aeromonas hydrophila", "Streptococcus pyogenes", "Clostridium perfringens"]'::jsonb, 2, 'Aeromonas hydrophila lives symbiotically in the digestive tract of the medicinal leech. Infection can rapidly destroy the flap. Prophylaxis with a fluoroquinolone (e.g., ciprofloxacin) or a third-generation cephalosporin is mandatory.'),
    (v_topic_id, 'What is the most common benign soft tissue tumor of the head and neck in adults?', '["Lipoma", "Hemangioma", "Schwannoma", "Fibroma", "Pleomorphic adenoma"]'::jsonb, 0, 'Lipomas are extremely common, slow-growing, encapsulated benign tumors composed of mature adipocytes. They typically present as soft, doughy, mobile subcutaneous masses.'),
    (v_topic_id, 'A 50-year-old male presents with a rock-hard, non-tender, fixed mass in the posterior triangle (Level V) of the neck. Complete head and neck examination is negative. While waiting for the FNA results, what primary malignancy must be high on the differential diagnosis for a mass specifically in Level V?', '["Nasopharyngeal carcinoma", "Laryngeal carcinoma", "Thyroid carcinoma", "Malignancy of the scalp, skin of the posterior neck, or a lymphoma", "Oral cavity carcinoma"]'::jsonb, 3, 'Level V (the posterior triangle) is the primary drainage basin for the posterior scalp and skin of the neck. It is also a very common site for the presentation of lymphoma. Oral cavity and laryngeal cancers rarely metastasize isolated to Level V without first involving Levels II-IV.'),
    (v_topic_id, 'A 60-year-old man undergoes a total laryngectomy and bilateral neck dissections. The surgeon must routinely dissect and preserve the phrenic nerve. Where is the phrenic nerve located anatomically in the neck?', '["Superficial to the sternocleidomastoid muscle", "Deep to the anterior scalene muscle", "Superficial to the anterior scalene muscle, coursing obliquely from lateral to medial", "Within the carotid sheath, between the artery and vein", "Attached to the inferior pole of the thyroid gland"]'::jsonb, 2, 'The phrenic nerve (C3, C4, C5) lies directly on the anterior surface of the anterior scalene muscle beneath the prevertebral fascia. It must be carefully identified and preserved to prevent diaphragmatic paralysis.'),
    (v_topic_id, 'During a neck dissection, the surgeon encounters the cervical rootlets of the brachial plexus. These nerve roots emerge BETWEEN which two muscles?', '["The sternocleidomastoid and the trapezius", "The anterior scalene and the middle scalene muscles", "The middle scalene and the posterior scalene muscles", "The digastric and the stylohyoid muscles", "The omohyoid and the sternohyoid muscles"]'::jsonb, 1, 'The roots of the brachial plexus (and the subclavian artery) pass through the interscalene triangle, which is bordered anteriorly by the anterior scalene and posteriorly by the middle scalene.'),
    (v_topic_id, 'What is the most common histological variant of malignant melanoma?', '["Nodular melanoma", "Superficial spreading melanoma", "Lentigo maligna melanoma", "Acral lentiginous melanoma", "Desmoplastic melanoma"]'::jsonb, 1, 'Superficial spreading melanoma is the most common type overall (about 70%). However, in the sun-exposed head and neck of the elderly, lentigo maligna melanoma is disproportionately common.'),
    (v_topic_id, 'Which variant of melanoma classically presents on the chronically sun-damaged faces of elderly patients as a slowly expanding, flat, irregularly pigmented macule that has been present for years before becoming invasive?', '["Nodular melanoma", "Superficial spreading melanoma", "Lentigo maligna melanoma", "Acral lentiginous melanoma", "Amelanotic melanoma"]'::jsonb, 2, 'Lentigo maligna is the in-situ precursor. When it invades the dermis, it becomes Lentigo Maligna Melanoma. It is characterized by a prolonged radial growth phase before vertical invasion occurs.'),
    (v_topic_id, 'Which variant of melanoma is known for being highly aggressive, lacking a radial growth phase entirely (meaning it grows vertically and invades deeply from the very beginning), and presenting as a dark, raised, dome-shaped lesion?', '["Lentigo maligna melanoma", "Superficial spreading melanoma", "Nodular melanoma", "Acral lentiginous melanoma", "Mucosal melanoma"]'::jsonb, 2, 'Because nodular melanoma lacks a horizontal/radial growth phase, it invades deeply very early, resulting in a higher Breslow depth at presentation and a worse prognosis compared to other types.'),
    (v_topic_id, 'A 60-year-old male presents with a firm, flesh-colored, non-pigmented nodule on his cheek. It has grown rapidly. Biopsy reveals a spindle cell malignancy that stains positively for S-100 and SOX10. What is the diagnosis?', '["Squamous cell carcinoma", "Basal cell carcinoma", "Desmoplastic melanoma", "Merkel cell carcinoma", "Dermatofibrosarcoma protuberans"]'::jsonb, 2, 'Desmoplastic melanoma is a rare, aggressive variant that is frequently amelanotic (lacks pigment), making it very difficult to diagnose clinically. It often presents as a firm, scar-like mass and has a high propensity for perineural invasion.'),
    (v_topic_id, 'In the evaluation of a patient with a T3 squamous cell carcinoma of the larynx, a PET-CT scan demonstrates intense FDG uptake in the primary tumor and a 2-cm right level II lymph node. What does the SUV (Standardized Uptake Value) on a PET scan actually measure?', '["The physical density of the tissue", "The relative metabolic activity based on the cellular uptake of a radiolabeled glucose analog (fluorodeoxyglucose)", "The amount of oxygen flowing to the tumor", "The density of the blood vessels (vascularity) of the tumor", "The specific number of dividing cells"]'::jsonb, 1, 'PET scans exploit the Warburg effect (cancer cells rely heavily on glycolysis). FDG is a glucose analog that is taken up by metabolically active cells but cannot be fully metabolized, thus accumulating and emitting positrons that are detected by the scanner.'),
    (v_topic_id, 'What is the primary physiological limitation or "blind spot" when using a PET scan to evaluate the brain or urinary tract?', '["These organs block positrons", "High physiologic baseline metabolic activity in the brain (glucose use) and the urinary excretion of the FDG radiotracer mask pathologic uptake in these areas", "The scanner cannot penetrate the skull or pelvis", "The tumors in these areas do not use glucose", "The radiotracer causes immediate seizures"]'::jsonb, 1, 'Because the brain uses glucose as its primary fuel, the entire brain "lights up" on a PET scan, making it difficult to spot a metastasis. Similarly, the kidneys and bladder concentrate the excreted tracer, masking tumors in the renal pelvis or bladder.'),
    (v_topic_id, 'A patient receives definitive radiation therapy to the neck for squamous cell carcinoma. Five years later, he presents with severe hypothyroidism. What is the most appropriate management?', '["Immediate total thyroidectomy", "Lifelong levothyroxine replacement therapy", "Radioactive iodine ablation", "Administration of propylthiouracil (PTU)", "Observation only"]'::jsonb, 1, 'Radiation-induced primary hypothyroidism is a very common late complication of external beam radiation therapy to the lower neck. The treatment is simple hormone replacement.'),
    (v_topic_id, 'Which of the following chemotherapeutic agents, sometimes used in advanced head and neck cancer, is notorious for causing dose-dependent, cumulative, and irreversible cardiomyopathy?', '["Cisplatin", "5-Fluorouracil (5-FU)", "Doxorubicin (Adriamycin)", "Methotrexate", "Bleomycin"]'::jsonb, 2, 'Doxorubicin is an anthracycline. Its most feared toxicity is irreversible dilated cardiomyopathy leading to congestive heart failure. A patient''s lifetime cumulative dose is strictly limited.'),
    (v_topic_id, 'Bleomycin is sometimes utilized in combination chemotherapy regimens. What is the classic, severe, dose-limiting toxicity associated with Bleomycin?', '["Nephrotoxicity", "Pulmonary toxicity leading to interstitial pneumonitis and pulmonary fibrosis", "Hepatotoxicity", "Peripheral neuropathy", "Cardiomyopathy"]'::jsonb, 1, 'Bleomycin causes pulmonary fibrosis. Patients exposed to bleomycin are at high risk of developing severe acute respiratory distress syndrome (ARDS) if they are exposed to high concentrations of oxygen (e.g., during general anesthesia).'),
    (v_topic_id, 'What is the most common paraneoplastic syndrome associated with Squamous Cell Carcinoma of the head and neck, lungs, and esophagus?', '["Syndrome of Inappropriate Antidiuretic Hormone (SIADH)", "Hypercalcemia of malignancy (mediated by secretion of Parathyroid Hormone-related Protein, PTHrP)", "Cushing syndrome", "Myasthenia gravis", "Lambert-Eaton myasthenic syndrome"]'::jsonb, 1, 'Squamous cell carcinomas frequently secrete PTHrP, which mimics normal PTH, leading to severe hypercalcemia, hypophosphatemia, and lethargy.'),
    (v_topic_id, 'A patient with an advanced, ulcerated oropharyngeal cancer presents with severe malnutrition (BMI 15). The surgical team places a feeding tube and aggressively starts high-calorie enteral feeds. Two days later, the patient develops severe hypophosphatemia, hypokalemia, and respiratory failure. What is the diagnosis?', '["Tumor lysis syndrome", "Refeeding syndrome", "Sepsis", "Carotid blowout", "Acute kidney injury"]'::jsonb, 1, 'Refeeding syndrome occurs when a chronically starved patient is suddenly given a high carbohydrate load. The surge in insulin causes rapid intracellular shifts of potassium, magnesium, and critically, phosphate, leading to fatal arrhythmias and respiratory failure.'),
    (v_topic_id, 'To prevent Refeeding Syndrome in a severely malnourished head and neck cancer patient, how should nutritional support be initiated?', '["Start at maximum caloric goal immediately to reverse weight loss", "Start feeds very slowly (e.g., 20-25% of goal calories) and aggressively monitor and replete electrolytes (especially phosphate, potassium, magnesium) before advancing", "Give intravenous glucose boluses", "Administer high doses of insulin", "Only provide parenteral (IV) nutrition"]'::jsonb, 1, 'Slow, graded initiation of caloric support with meticulous electrolyte replacement is essential to safely refeed a severely malnourished patient.')
